('av_aPtTn4ukHdTOWZauwqp_XOM8muwQ_cjwnUwUa3SpQxaa9Pluycs353XF7lG-ULWwFv3VzO1PRk-ASoM','谁让这个悍匪修仙的',2026,'short_drama','中国大陆','国语','["AI漫剧","古装仙侠","短剧"]','[]','[]','https://gimg0.baidu.com/gimg/app=2001&n=0&g=0n&fmt=webp&src=img.baipiaozhe.com/assets/images/ee/eead3b8be71b0b95c9c85c8f06b4fb73307858fcf43811f1af43339156aeda3b.webp',NULL,'说实话,看到这个标题的时候我就知道这部剧不简单 。 男主赵铁柱原本是江湖上赫赫有名的大悍匪,烧杀抢掠无恶不作,结果在某次打家劫舍时意外救了一个濒死的散修 。 对方为了报恩,把毕生修为全灌给了他,于是这个大字不识几个的土匪稀里糊涂开始了修仙之路 。 这个设定真的太绝了,一个满嘴脏话 、 动辄动手的糙汉修士,怎么看怎么违和 。 但偏偏他的修炼速度还快得吓人,因为他打架不要命的狠劲刚好契合某些功法的要求 。AI 制作把这种反差感处理得很好,男主施法时的手势和念咒时的磕磕绊绊形成了一种独特的喜感 。80 集的体量足够把悍匪修士的成长之路铺陈完整,从被人嘲笑的野路子到一巴掌拍死筑基高手,这种爽感谁懂 。 而且剧中对传统修仙体系的吐槽也很到位,非常适合喜欢反套路的观众 。','更新至60集',60,60,54.53,'最近更新 第60集'),
('av_aQrGX_kWykzSPj7Q_DLwTKOO5GVO5Z2mBlV7gQL-e__DDdlGmcQSOBWP0xnaw06fcEcf_RFawpSHoIY','花儿与少年·同心季',2025,'variety','中国大陆','国语','["大陆综艺","真人秀","综艺","旅游"]','["陈数","龚俊","李沁","马思纯","那英","张晚意","张雅琪"]','["李超"]','https://gimg0.baidu.com/gimg/app=2001&n=0&g=0n&fmt=webp&src=img.baipiaozhe.com/assets/images/e6/e6ed7133b29b8144ebc45a5d6df460c2aa397f422bc53de4dddecb0e72ad3746.webp','https://gimg0.baidu.com/gimg/app=2001&n=0&g=0n&fmt=webp&src=img.baipiaozhe.com/assets/images/25/25e453496cb5bb91e30c3ac3d886da055c9ef7d518d18ce5a050f6e18fd1d10f.webp','全方位记录花少团在共建“一带一路”合作项目、中外民间交流、中企海外发展等多维场景下的真实体验,生动诠释“同舟共济·同心协力”的时代主题,呈现中国与世界共建共享、命运与共的青春故事。','20251125一口气看埃及站',171,171,86.01,NULL),
('av_aS5sJjUNQuEp5hWN8_KbZF_HUz-5tHROW2zECIGB5nV8FaJ1ONavtU2i7hzETD2OkqldltlJl4d8qUM','死亡笔记',2006,'anime','日本','日语','["日本动漫","动漫","剧情","奇幻","惊悚","犯罪","悬疑","日韩动漫"]','["宫野真守","平野绫","山口胜平","中村狮童","内田直哉","中井和哉","坂本真绫","工藤晴香","日高法子","松风雅也","佐佐木望"]','["荒木哲郎"]','https://gimg0.baidu.com/gimg/app=2001&n=0&g=0n&fmt=webp&src=img.baipiaozhe.com/assets/images/d8/d8c2a6c76c24603a6f783146c03f01b0c62818f0def04c0dc25709b4d1d4844b.webp','https://gimg0.baidu.com/gimg/app=2001&n=0&g=0n&fmt=webp&src=img.baipiaozhe.com/assets/images/ce/ce01f105b113de8b08c43c24d4dc1ab38b74d5457892e1795341eb9f8688a109.webp',NULL,'更新至37集',NULL,NULL,114.43,'2026-11-03T05:35:24.297Z'),
('av_aSAgPYWeY1tZ0TznLUS-2qVrfuyrnw-RPzcnI7p3clIXJa8xTd04tLZ1fzMEze3Xi-7G_Hsqg8p2Pfo','十日谈',1971,'movie','意大利',NULL,'["喜剧","剧情","爱情","历史","电影"]','["安吉拉·露西","弗兰科·奇蒂","圭多·阿尔贝蒂","圭多·曼纳里","贾尼·埃斯波西托","玛丽亚·加布里埃拉·玛雅","莫妮","尼内托·达沃利","帕特里齐娅·德·克拉拉","皮埃尔·保罗·帕索里尼","文森佐·阿马托","Vincenzo"]','["皮埃尔·保罗·帕索里尼"]','https://gimg0.baidu.com/gimg/app=2001&n=0&g=0n&fmt=webp&src=img.baipiaozhe.com/assets/images/e6/e628ff804c97943f448242e51e98799b3f5e74e053cd30b78495766dd0bb47e8.webp',NULL,'获柏林电影节评审团大奖。影片取材于意大利文艺复兴时期薄伽丘的著名小说集《十日谈》,帕索里尼从中挑选了8个(亦有说10个)发生在那不勒斯等意大利南部地区的故事进行拍摄(原著中以佛罗伦萨地区故事为主),这些故事大多以揭露教会虚伪丑恶本质为宗旨,并鲜明地表现了作者对人性解放的肯定态度。 原著《十日谈》是意大利文艺复兴时期最重要的文学作品之一,它以十四世纪黑死病横行的时期为背景,通过十位青年所讲述的一百个故事,大胆鞭挞了当时天主教会的种种丑行,表现出平民阶层追求自由、摆脱宗教束缚的渴望。这部现实主义风格明显的作品堪称欧洲古典文学的杰作,被后人誉为和但丁《神曲》齐名的 人曲。 意大利新现实主义影片后期崛起的导演帕索里尼,延续了自己六十年代以古代神话题材警醒当今世人的创作路线,以相对通俗化的手法连续改编拍摄了《十日谈》、《坎特伯雷故事》和《一千零一夜》三部古典名著影片,合称生命三部曲。因为这三部影片中裸露镜头较多,又采用了较为通俗的娱乐片路线,有的电影学者也称之为帕索里尼的色情三部曲。对此帕索里尼本人阐述了自己的创作观点:我向观众表现的是整个世界,封建的世界,在这个世界里,情欲极其深刻而狂热地起着支配一切的作用。......我要推出这个世界并且说:你们可以比较一下,我要向你们表明,我要向你们诉说,我要向你们提醒。','高清',2,1,100.15,'最近上线 意大利语中字-AWKN'),
('av_aSqDbcTkT1tsoT__EQ7kdvLJXkZMCGZFn2mq0MUmARd7SRypd4T4qH570mHQ9-6VSXYmmRgce2kJ8Xk','偶滴歌神啊 第3季',2016,'variety','中国大陆','国语','["大陆综艺","音乐","真人秀","综艺","爱奇艺出品","竞演"]','["谢娜","李斯羽","黄乔歆","刘忻","徐浩","杨迪","臧一人","张大大","李谯玉","王芯芯","杨青竹","陈俊"]','[]','https://gimg0.baidu.com/gimg/app=2001&n=0&g=0n&fmt=webp&src=img.baipiaozhe.com/assets/images/cc/cc1f18c1d238b1a72ce4113a39cf1d97d232c89ea8539ced1b229230f9fbe175.webp',NULL,'《偶滴歌神啊第三季》是由爱奇艺视频网站出品的一档非大型、不靠谱、伪音乐类纯网络综艺节目。《偶滴歌神啊》节目才不断的创造着收视奇迹,而作为谢娜首次单独主持的综艺节目,也算是给观众们交上了一副满意的答卷。','2016-10-13',29,29,56.78,'2026-11-12T20:20:03.227Z'),
